SELECT o.status, CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END order_cohort, MAX(oi.quantity) - MIN(oi.quantity) quantity_range FROM order_items oi INNER JOIN orders o ON oi.order_id = o.id WHERE oi.product_id = 38 GROUP BY o.status, CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING MAX(oi.quantity) - MIN(oi.quantity) > 71
